def decode_ways(s: str) -> int:
    if not s:
        return 1
    if s[0] == '0':
        return 0
    ways = [0] * len(s)
    ways[0] = 1
    for i in range(1, len(s)):
        if s[i] != '0':
            ways[i] = ways[i-1]
        if 10 <= int(s[i-1:i+1]) <= 26:
            ways[i] += ways[i-2] if i >= 2 else 0
    return ways[-1]
