def caesar_shift(s: str, k: int) -> str:
    result = ""
    for char in s:
        if char.isalpha():
            ascii_offset = ord('a') if char.islower() else ord('A')
            shifted_char = chr((ord(char) - ascii_offset + k) % 26 + ascii_offset)
            result += shifted_char
        else:
            result += char
    return result
