def spiral_order(matrix: list[list[int]]) -> list[int]:
    if not matrix:
        return []

    rows, cols = len(matrix), len(matrix[0])
    seen = [[False] * cols for _ in range(rows)]
    result = []
    dr, dc = 0, 1

    for _ in range(rows * cols):
        result.append(matrix[dr][dc])
        seen[dr][dc] = True
        if dr + 1 < rows and not seen[dr + 1][dc]:
            dr, dc = dr + 1, dc
        elif dc + 1 < cols and not seen[dr][dc + 1]:
            dr, dc = dr, dc + 1
        elif dr - 1 >= 0 and not seen[dr - 1][dc]:
            dr, dc = dr - 1, dc
        elif dc - 1 >= 0 and not seen[dr][dc - 1]:
            dr, dc = dr, dc - 1
        else:
            break

    return result
