from collections import deque

def sliding_max(nums: list[int], k: int) -> list[int]:
    if k == 1:
        return nums
    max_q = deque()
    res = []
    for i, num in enumerate(nums):
        while max_q and nums[max_q[-1]] <= num:
            max_q.pop()
        max_q.append(i)
        if i - max_q[0] >= k:
            max_q.popleft()
        if i >= k - 1:
            res.append(nums[max_q[0]])
    return res
```

