def decode_ways(s: str) -> int:
    if not s:
        return 1
    if s[0] == '0':
        return 0
    ways = 0
    prev = s[0]
    for i in range(1, len(s)):
        curr = s[i]
        if curr == '0':
            if prev == '1' or prev == '2':
                ways += decode_ways(s[i+1:])
        elif prev == '1' and curr >= '0' and curr <= '9':
            ways += decode_ways(s[i+1:])
        elif prev == '2' and curr >= '0' and curr <= '6':
            ways += decode_ways(s[i+1:])
        prev = curr
    return ways + int(prev != '0')
