def is_safe(board, row, col, n):
    # Check if there is a queen in the same column or in the left top diagonal or right top diagonal
    for i in range(row):
        if board[i] == col or abs(board[i] - col) == row - i:
            return False
    return True

def count_queens(n):
    def backtrack(row, board):
        nonlocal count
        if row == n:
            count += 1
            return
        for col in range(n):
            if is_safe(board, row, col, n):
                board[row] = col
                backtrack(row + 1, board)

    count = 0
    board = [-1] * n
    backtrack(0, board)
    return count

def n_queens(n: int) -> int:
    if n < 1 or n > 10:
        raise ValueError("n must be between 1 and 10")
    return count_queens(n)
