Here's a Python function that uses the `ast` module to parse the expression and then evaluates it. It handles the operators and precedence as specified.

```python
import ast

def evaluate(expr: str) -> int:
    class EvalAST(ast.NodeTransformer):
        def visit_BinOp(self, node):
            if isinstance(node.op, ast.Add):
                node.op = ast.Add()
            elif isinstance(node.op, ast.Sub):
                node.op = ast.Sub()
            elif isinstance(node.op, ast.Mult):
                node.op = ast.Mult()
            elif isinstance(node.op, ast.Div):
                node.op = ast.FloorDiv()  # Integer division truncates toward zero
            return self.generic_visit(node)

    def evaluate_node(node):
        if isinstance(node, ast.Num):
            return node.n
        elif isinstance(node, ast.BinOp):
            left = evaluate_node(node.left)
            right = evaluate_node(node.right)
            return {
                ast.Add(): lambda x, y: x + y,
                ast.Sub(): lambda x, y: x - y,
                ast.Mult(): lambda x, y: x * y,
                ast.FloorDiv(): lambda x, y: x // y,
            }[type(node.op)](left, right)
        elif isinstance(node, ast.Expr):
            return evaluate_node(node.value)

    return evaluate_node(ast.parse(expr, mode='eval').body)

