To solve this problem, we can use backtracking. We'll place queens one by one in different columns, checking at each step if it's safe to place a queen in the current column. If it's safe, we recursively place queens in the remaining columns.

Here's the Python function that implements this:

```python
def is_safe(board, row, col, n):
    # Check if there is a queen in the same column in the above rows
    for i in range(row):
        if board[i][col] == 1:
            return False

    # Check if there is a queen in the upper left diagonal
    i, j = row, col
    while i >= 0 and j >= 0:
        if board[i][j] == 1:
            return False
        i -= 1
        j -= 1

    # Check if there is a queen in the upper right diagonal
    i, j = row, col
    while i >= 0 and j < n:
        if board[i][j] == 1:
            return False
        i -= 1
        j += 1

    return True

def n_queens(n: int) -> int:
    board = [[0]*n for _ in range(n)]
    count = 0

    def backtrack(row):
        nonlocal count
        if row == n:
            count += 1
            return

        for col in range(n):
            if is_safe(board, row, col, n):
                board[row][col] = 1
                backtrack(row + 1)
                board[row][col] = 0

    backtrack(0)
    return count

