```python
def regex_match(s: str, p: str) -> bool:
    def match(s, p):
        if len(p) == 0:
            return len(s) == 0
        elif len(p) == 1 or p[1] != '*':
            return len(s) > 0 and (p[0] == '.' or p[0] == s[0]) and match(s[1:], p[1:])
        else:
            while len(s) > 0 and (p[0] == '.' or p[0] == s[0]):
                if match(s, p[2:]):
                    return True
                s = s[1:]
            return match(s, p[2:])

    return match(s, p)
