def n_queens(n: int) -> int:
    def is_safe(board, row, col):
        for i in range(row):
            if board[i] == col or abs(board[i] - col) == abs(i - row):
                return False
        return True

    def backtrack(board, row):
        if row == n:
            return 1
        solutions = 0
        for col in range(n):
            if is_safe(board, row, col):
                board[row] = col
                solutions += backtrack(board, row + 1)
        return solutions

    board = [-1] * n
    return backtrack(board, 0)

